const err = $input.first().json;
const wf = err.workflow || {};
const exec = err.execution || {};
const error = err.execution?.error || {};
const lastNode = err.execution?.lastNodeExecuted || '(unknown)';

const preview = (() => {
  try {
    return JSON.stringify(err, null, 2).slice(0, 2000);
  } catch (e) {
    return String(err).slice(0, 2000);
  }
})();

const execUrl = exec.id
  ? `https://ops.tandemcoach.co/workflow/${wf.id}/executions/${exec.id}`
  : '(no execution id)';

const text = [
  `:rotating_light: *n8n workflow failure*`,
  `*Workflow:* ${wf.name || wf.id || '(unknown)'}`,
  `*Failed node:* ${lastNode}`,
  `*Error:* ${error.message || '(no message)'}`,
  `*Execution:* ${execUrl}`,
  '',
  '```',
  preview,
  '```',
].join('\n');

return [{ json: { channel: 'C0AHDHX1NBH', text } }];
